script: |
const fs = require('fs');
const owner = context.repo.owner;
const repo = context.repo.repo;
const MAX_TITLE_CHARS = 200;
const MAX_BODY_CHARS = 1200;
function truncate(str, max) {
if (!str) return '';
const s = String(str);
return s.length > max ? s.slice(0, max) + '...[truncated]' :
s;
}
function sanitize(str) {
if (!str) return '';
return String(str).replace(/```/g, '`');
}
const commits = context.payload.commits ?? [];
const prsByNumber = new Map();
for (const commit of commits) {
const associatedPrs = await github.paginate(
github.rest.repos.listPullRequestsAssociatedWithCommit,
{
owner,
repo,
commit_sha: commit.id,
per_page: 100,
}
);
for (const pr of associatedPrs) {
if (!pr.merged_at) continue;
if (pr.base?.ref !== 'main') continue;
if (!prsByNumber.has(pr.number)) {
prsByNumber.set(pr.number, {
number: pr.number,
title: truncate(sanitize(pr.title), MAX_TITLE_CHARS),
77 Integrating Generative AI Into DevOps Pipelines
labels: (pr.labels ?? []).map(l => l.name),
author: pr.user?.login ?? null,
body: truncate(sanitize(pr.body ?? ''),

MAX_BODY_CHARS),
});
}
}
}
const report = {
generated_at: new Date().toISOString(),
repository: `${owner}/${repo}`,
pull_requests: Array.from(prsByNumber.values()),
};
fs.writeFileSync('release-report.json', JSON.stringify(report,
null, 2));
core.info(`Wrote release-report.json with $
{report.pull_requests.length} merged PR(s).`);
const prCount = report.pull_requests.length;
core.setOutput('pr_count', String(prCount));
- name: Upload release input artifact
uses: actions/upload-artifact@v4
with:
name: release-input
path: release-report.json
The workflow idx_21ab8f3d deliberately uses release ‑ report.json as a handoff file. That file becomes the
controlled user input for the AI generation step.
Step 3: Generating release notes with AI
Make the idx_d48e9b0d generation job depend on the metadata collection job.
Attach the job to the devops ‑ dev environment so it can access the Azure OpenAI
environment secrets.
Download the release ‑ input artifact so the job can read release ‑ report.json.
